mountPattern(9, pat('x(9,16)').gsteps(16))
for (let n = 1; n <= 16; n++) mountPattern(n + 9, pat('x(' + n + ',16)').gsteps(16))
for (let n = 1; n <= 10; n++) mountPattern(n + 25, pat('x(' + n + ',12)').gsteps(12))
